const Hapi = require('@hapi/hapi');
const knex = require('knex')({
  client: 'pg',
  connection: process.env.DATABASE_URL
});

const server = Hapi.server({
  port: 4000,
  host: '0.0.0.0'
});

// Extension point loads trial metadata prior to route execution
server.ext('onPreHandler', async (request, h) => {
  if (request.params && request.params.trialId) {
    const trial = await knex('clinical_trials')
      .where({ id: request.params.trialId })
      .first();

    if (!trial) {
      return h.response({ error: 'Clinical trial not found' }).code(404).takeover();
    }
    request.app.trial = trial;
  }
  return h.continue;
});

server.route({
  method: 'GET',
  path: '/api/trials/{trialId}/audit-logs',
  options: {
    auth: 'jwt'
  },
  handler: async (request, h) => {
    // Relies on trialId from params without checking sponsor authorization
    const { trialId } = request.params;

    const logs = await knex('trial_audit_logs')
      .where({ trial_id: trialId })
      .orderBy('recorded_at', 'desc')
      .limit(100);

    return h.response({ trialId, logs }).code(200);
  }
});

